func goList(patterns []string) ([]PackageJSON, error) {
    args := append([]string{"list", "-json"}, patterns...)
    cmd := exec.Command("go", args...)
    var out, errb bytes.Buffer
    cmd.Stdout = &out
    cmd.Stderr = &errb
    if err := cmd.Run(); err != nil {
        s := errb.String()
        if s == "" { s = err.Error() }
        return nil, errors.New(s)
    }
    dec := json.NewDecoder(&out)
    var pkgs []PackageJSON
    for {
        var p PackageJSON
        if err := dec.Decode(&p); err != nil {
            if errors.Is(err, io.EOF) { break }
            return nil, err
        }
        pkgs = append(pkgs, p)
    }
    return pkgs, nil
}

func analyzePackage(p PackageJSON, cfg Config, opts Options, includeTests bool) ([]Diagnostic, error) {
    fset := token.NewFileSet()
    var files []*ast.File
    names := append([]string{}, p.GoFiles...)
    if opts.test && includeTests { names = append(names, p.TestGoFiles...) }
    for _, n := range names {
        path := n
        if !filepath.IsAbs(path) { path = filepath.Join(p.Dir, n) }
        f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
        if err != nil { return nil, err }
        files = append(files, f)
    }
    info := &types.Info{
        Types:      map[ast.Expr]types.TypeAndValue{},
        Defs:       map[*ast.Ident]types.Object{},
        Uses:       map[*ast.Ident]types.Object{},
        Implicits:  map[ast.Node]types.Object{},
        Selections: map[*ast.SelectorExpr]*types.Selection{},
    }
    conf := types.Config{Importer: newHybridImporter(), Error: func(error) {}}
    tpkg, _ := conf.Check(p.ImportPath, fset, files, info)
    if tpkg == nil { tpkg = types.NewPackage(p.ImportPath, p.Name) }
    a := &Analyzer{cfg: cfg, fset: fset, files: files, pkg: tpkg, info: info, pkgPath: p.ImportPath, origins: map[types.Object]Origin{}, fileLineCache: map[string][]string{}}
    for _, r := range cfg.IgnoreSigRegexps {
        rr, err := regexp.Compile(r); if err != nil { return nil, fmt.Errorf("unable to compile regexp %s: %v", r, err) }
        a.sigRegexps = append(a.sigRegexps, rr)
    }
    for _, r := range cfg.IgnoreInterfaceRegexps {
        rr, err := regexp.Compile(r); if err != nil { return nil, fmt.Errorf("unable to compile regexp %s: %v", r, err) }
        a.ifaceRegexps = append(a.ifaceRegexps, rr)
    }
    for _, f := range files { a.walkFile(f) }
    sortDiagnostics(a.diagnostics)
    return a.diagnostics, nil
}

func newHybridImporter() types.ImporterFrom {
    return &sourceImporter{base: importer.ForCompiler(token.NewFileSet(), "source", nil), cache: map[string]*types.Package{}}
}

type sourceImporter struct { base types.Importer; cache map[string]*types.Package }
func (s *sourceImporter) Import(path string) (*types.Package, error) { return s.ImportFrom(path, "", 0) }
func (s *sourceImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
    if p, ok := s.cache[path]; ok { return p, nil }
    if ifrom, ok := s.base.(types.ImporterFrom); ok {
        if p, err := ifrom.ImportFrom(path, dir, mode); err == nil { s.cache[path] = p; return p, nil }
    } else if p, err := s.base.Import(path); err == nil { s.cache[path] = p; return p, nil }
    bp, err := build.Default.Import(path, dir, build.FindOnly)
    if err != nil { return nil, err }
    fset := token.NewFileSet()
    var files []*ast.File
    for _, n := range bp.GoFiles {
        f, err := parser.ParseFile(fset, filepath.Join(bp.Dir, n), nil, 0); if err == nil { files = append(files, f) }
    }
    pkg := types.NewPackage(path, bp.Name)
    s.cache[path] = pkg
    conf := types.Config{Importer: s, Error: func(error){}}
    checked, err := conf.Check(path, fset, files, nil)
    if checked != nil { s.cache[path] = checked; return checked, nil }
    return pkg, err
}

func (a *Analyzer) walkFile(f *ast.File) {
    ast.Inspect(f, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.FuncDecl:
            a.walkFunc(x.Body)
            return false
        case *ast.FuncLit:
            a.walkFunc(x.Body)
            return false
        }
        return true
    })
}

func (a *Analyzer) walkFunc(body *ast.BlockStmt) {
    if body == nil { return }
    ast.Inspect(body, func(n ast.Node) bool {
        if n == nil { return true }
        switch x := n.(type) {
        case *ast.AssignStmt:
            a.handleAssign(x.Lhs, x.Rhs)
        case *ast.ValueSpec:
            a.handleValueSpec(x)
        case *ast.ReturnStmt:
            a.handleReturn(x)
        }
        return true
    })
}

func (a *Analyzer) handleValueSpec(v *ast.ValueSpec) {
    if len(v.Values) == 0 { return }
    var origins []Origin
    if len(v.Values) == 1 {
        origins = a.originsForExpr(v.Values[0])
    } else {
        for _, e := range v.Values { origins = append(origins, firstOrigin(a.originsForExpr(e))) }
    }
    for i, name := range v.Names {
        obj := a.info.Defs[name]
        if obj == nil { obj = a.info.Uses[name] }
        if obj == nil { continue }
        if i < len(origins) && origins[i].Sig != "" && isErrorType(obj.Type()) { a.origins[obj] = origins[i] } else { delete(a.origins, obj) }
    }
}

func (a *Analyzer) handleAssign(lhs []ast.Expr, rhs []ast.Expr) {
    var origins []Origin
    if len(rhs) == 1 {
        origins = a.originsForExpr(rhs[0])
    } else {
        for _, e := range rhs { origins = append(origins, firstOrigin(a.originsForExpr(e))) }
    }
    for i, le := range lhs {
        id, ok := le.(*ast.Ident); if !ok || id.Name == "_" { continue }
        obj := a.info.Defs[id]; if obj == nil { obj = a.info.Uses[id] }
        if obj == nil { continue }
        if i < len(origins) && origins[i].Sig != "" && isErrorType(obj.Type()) { a.origins[obj] = origins[i] } else { delete(a.origins, obj) }
    }
}

func (a *Analyzer) handleReturn(r *ast.ReturnStmt) {
    for _, e := range r.Results {
        os := a.originsForExpr(e)
        if len(os) == 0 { continue }
        // For multi-result calls, only diagnostics for error result origins are returned in originsForExpr.
        for _, o := range os {
            if o.Sig == "" || o.Suppressed { continue }
            a.report(e, o)
            // A single returned expression should produce at most one diagnostic in normal Go error-return code.
            break
        }
    }
}

func firstOrigin(os []Origin) Origin { if len(os) > 0 { return os[0] }; return Origin{} }

func (a *Analyzer) originsForExpr(e ast.Expr) []Origin {
    if e == nil { return nil }
    tv, ok := a.info.Types[e]
    switch x := e.(type) {
    case *ast.Ident:
        if obj := a.info.Uses[x]; obj != nil {
            if o, ok := a.origins[obj]; ok { return []Origin{o} }
        }
        return nil
    case *ast.CallExpr:
        o := a.originForCall(x)
        if o.Sig == "" { return nil }
        // A tuple call contributes origin only for error-valued results.
        sig, _ := a.typeOf(x.Fun).(*types.Signature)
        if sig == nil { return []Origin{o} }
        res := sig.Results()
        if res == nil || res.Len() == 0 { return nil }
        var out []Origin
        for i:=0; i<res.Len(); i++ { if isErrorType(res.At(i).Type()) { out = append(out, o) } else { out = append(out, Origin{}) } }
        return out
    case *ast.ParenExpr:
        return a.originsForExpr(x.X)
    case *ast.TypeAssertExpr:
        return a.originsForExpr(x.X)
    }
    if ok && isErrorType(tv.Type) {
        return nil
    }
    return nil
}

func (a *Analyzer) typeOf(e ast.Expr) types.Type {
    if tv, ok := a.info.Types[e]; ok { return tv.Type }
    return nil
}

func (a *Analyzer) originForCall(c *ast.CallExpr) Origin {
    sig, _ := a.typeOf(c.Fun).(*types.Signature)
    if sig == nil { return Origin{} }
    if !signatureHasError(sig) { return Origin{} }
    sigstr := a.signatureString(c, sig)
    if a.ignoredSig(sigstr) { return Origin{Sig:sigstr, Suppressed:true} }
    pkgPath := a.callPackagePath(c)
    isIface := a.isInterfaceCall(c, sig)
    if isIface && a.ignoreInterface(sig) {
        isIface = false
    }
    internal := pkgPath == "" || pkgPath == a.pkgPath
    if isIface {
        return Origin{Sig:sigstr, PkgPath:pkgPath, Internal:internal, Interface:true}
    }
    if internal && !a.cfg.ReportInternalErrors { return Origin{Sig:sigstr, Suppressed:true} }
    if !internal && a.ignoredPackage(pkgPath) { return Origin{Sig:sigstr, Suppressed:true} }
    return Origin{Sig:sigstr, PkgPath:pkgPath, Internal:internal}
}

func signatureHasError(sig *types.Signature) bool {
    r := sig.Results(); if r == nil { return false }
    for i:=0; i<r.Len(); i++ { if isErrorType(r.At(i).Type()) { return true } }
    return false
}

func isErrorType(t types.Type) bool {
    if t == nil { return false }
    return types.Identical(t, types.Universe.Lookup("error").Type()) || types.AssignableTo(t, types.Universe.Lookup("error").Type())
}

func (a *Analyzer) callPackagePath(c *ast.CallExpr) string {
    switch f := c.Fun.(type) {
    case *ast.SelectorExpr:
        if sel := a.info.Selections[f]; sel != nil {
            if sel.Obj() != nil && sel.Obj().Pkg() != nil { return sel.Obj().Pkg().Path() }
            return typePkgPath(sel.Recv())
        }
        if obj := a.info.Uses[f.Sel]; obj != nil && obj.Pkg() != nil { return obj.Pkg().Path() }
    case *ast.Ident:
        if obj := a.info.Uses[f]; obj != nil && obj.Pkg() != nil { return obj.Pkg().Path() }
    }
    return ""
}

func typePkgPath(t types.Type) string {
    switch tt := t.(type) {
    case *types.Named:
        if tt.Obj()!=nil && tt.Obj().Pkg()!=nil { return tt.Obj().Pkg().Path() }
    case *types.Pointer:
        return typePkgPath(tt.Elem())
    case *types.Interface:
        return ""
    }
    return ""
}

func (a *Analyzer) isInterfaceCall(c *ast.CallExpr, sig *types.Signature) bool {
    if s, ok := c.Fun.(*ast.SelectorExpr); ok {
        if sel := a.info.Selections[s]; sel != nil {
            if _, ok := under(sel.Recv()).(*types.Interface); ok { return true }
        }
        // Fallback: inspect receiver type of the signature.
        if sig.Recv()!=nil { if _, ok := under(sig.Recv().Type()).(*types.Interface); ok { return true } }
    }
    return false
}

func under(t types.Type) types.Type { if t==nil { return nil }; return t.Underlying() }

func (a *Analyzer) ignoreInterface(sig *types.Signature) bool {
    if sig.Recv() == nil { return false }
    name := typeName(sig.Recv().Type())
    for _, r := range a.ifaceRegexps { if r.MatchString(name) { return true } }
    return false
}

func typeName(t types.Type) string {
    switch tt := t.(type) {
    case *types.Named:
        return tt.Obj().Name()
    case *types.Pointer:
        return typeName(tt.Elem())
    default:
        return types.TypeString(t, qualifier)
    }
}

func (a *Analyzer) signatureString(c *ast.CallExpr, sig *types.Signature) string {
    // types.Signature.String with a package-path qualifier closely matches observed output.
    return "func " + callName(c, a.info) + strings.TrimPrefix(types.TypeString(sig, qualifier), "func")
}

func callName(c *ast.CallExpr, info *types.Info) string {
    switch f := c.Fun.(type) {
    case *ast.Ident:
        if obj := info.Uses[f]; obj != nil {
            if obj.Pkg()!=nil { return obj.Pkg().Path()+"."+obj.Name() }
            return obj.Name()
        }
        return f.Name
    case *ast.SelectorExpr:
        if sel := info.Selections[f]; sel != nil {
            recv := types.TypeString(sel.Recv(), qualifier)
            if _, ok := sel.Recv().(*types.Pointer); ok {
                recv = types.TypeString(sel.Recv(), qualifier)
            }
            return "("+recv+")."+f.Sel.Name
        }
        if obj := info.Uses[f.Sel]; obj != nil {
            if obj.Pkg()!=nil { return obj.Pkg().Path()+"."+obj.Name() }
            return obj.Name()
        }
        return exprString(f.X)+"."+f.Sel.Name
    default:
        return exprString(f)
    }
}

func qualifier(p *types.Package) string { if p == nil { return "" }; return p.Path() }

func exprString(e ast.Expr) string {
    switch x := e.(type) {
    case *ast.Ident: return x.Name
    case *ast.SelectorExpr: return exprString(x.X)+"."+x.Sel.Name
    case *ast.StarExpr: return "*"+exprString(x.X)
    }
    return ""
}

func (a *Analyzer) ignoredSig(sig string) bool {
    ignores := defaultIgnoreSigs
    if a.cfg.hasIgnoreSigs { ignores = a.cfg.IgnoreSigs }
    ignores = append(append([]string{}, ignores...), a.cfg.ExtraIgnoreSigs...)
    for _, s := range ignores { if s != "" && strings.Contains(sig, s) { return true } }
    for _, r := range a.sigRegexps { if r.MatchString(sig) { return true } }
    return false
}

func (a *Analyzer) ignoredPackage(pkg string) bool {
    if pkg == "" { return false }
    for _, g := range a.cfg.IgnorePackageGlobs {
        if ok, _ := filepath.Match(g, pkg); ok { return true }
        if strings.Contains(g, "*") {
            // filepath.Match's * doesn't cross slashes. Treat globstars/segment globs liberally as a regexp-like glob.
            pat := regexp.QuoteMeta(g)
            pat = strings.ReplaceAll(pat, "\\*", ".*")
            if regexp.MustCompile("^"+pat+"$").MatchString(pkg) { return true }
        }
    }
    return false
}

func (a *Analyzer) report(e ast.Expr, o Origin) {
    pos := a.fset.Position(e.Pos())
    msg := "error returned from external package is unwrapped: sig: " + o.Sig
    if o.Interface { msg = "error returned from interface method should be wrapped: sig: " + o.Sig
    } else if o.Internal { msg = "package-internal error should be wrapped: sig: " + o.Sig }
    a.diagnostics = append(a.diagnostics, Diagnostic{Posn: fmt.Sprintf("%s:%d:%d", pos.Filename, pos.Line, pos.Column), Message: msg, pos: pos, file: pos.Filename})
}

func sortDiagnostics(ds []Diagnostic) { sort.Slice(ds, func(i,j int) bool { if ds[i].Posn==ds[j].Posn { return ds[i].Message<ds[j].Message }; return ds[i].Posn<ds[j].Posn }) }

func filterNonTest(ds []Diagnostic) []Diagnostic {
    var out []Diagnostic
    for _, d := range ds { if !strings.HasSuffix(d.file, "_test.go") { out = append(out, d) } }
    return out
}

func printContext(w io.Writer, file string, line, c int) {
    b, err := os.ReadFile(file); if err != nil { return }
    lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
    start := line - c; if start < 1 { start = 1 }
    end := line + c; if end > len(lines) { end = len(lines) }
    for i:=start; i<=end; i++ { fmt.Fprintf(w, "%d\t%s\n", i, lines[i-1]) }
}

func printJSONDiagnostics(m map[string][]Diagnostic) {
    type jd struct { Posn string `json:"posn"`; Message string `json:"message"` }
    out := map[string]map[string][]jd{}
    keys := make([]string,0,len(m)); for k := range m { keys=append(keys,k) }; sort.Strings(keys)
    for _, k := range keys {
        ds := m[k]; if len(ds)==0 { continue }
        sortDiagnostics(ds)
        arr := make([]jd,0,len(ds)); for _, d := range ds { arr=append(arr,jd{d.Posn,d.Message}) }
        out[k] = map[string][]jd{"wrapcheck": arr}
    }
    b, _ := json.MarshalIndent(out, "", "\t")
    os.Stdout.Write(b); os.Stdout.Write([]byte("\n"))
}

func loadConfig() (Config, error) {
    var cfg Config
    paths := []string{".wrapcheck.yaml", ".wrapcheck.yml"}
    if h, err := os.UserHomeDir(); err == nil && h != "" { paths = append(paths, filepath.Join(h,".wrapcheck.yaml"), filepath.Join(h,".wrapcheck.yml")) }
    for _, p := range paths {
        b, err := os.ReadFile(p); if err == nil { parseSimpleYAML(string(b), &cfg); break }
    }
    // Compile now, to match user-visible regexp errors.
    for _, r := range cfg.IgnoreSigRegexps { if _, err := regexp.Compile(r); err != nil { return cfg, fmt.Errorf("unable to compile regexp %s: %v", r, err) } }
    for _, r := range cfg.IgnoreInterfaceRegexps { if _, err := regexp.Compile(r); err != nil { return cfg, fmt.Errorf("unable to compile regexp %s: %v", r, err) } }
    return cfg, nil
}

func parseSimpleYAML(s string, cfg *Config) {
    var current string
    for _, raw := range strings.Split(s, "\n") {
        line := stripComment(raw)
        if strings.TrimSpace(line)=="" { continue }
        trimmed := strings.TrimSpace(line)
        if strings.HasPrefix(trimmed, "-") {
            val := strings.TrimSpace(strings.TrimPrefix(trimmed,"-")); val = unquote(val)
            addConfigValue(cfg, current, val)
            continue
        }
        if idx := strings.Index(trimmed, ":"); idx >= 0 {
            key := strings.TrimSpace(trimmed[:idx]); val := strings.TrimSpace(trimmed[idx+1:]); current = key
            if val == "" { continue }
            if strings.HasPrefix(val,"[") && strings.HasSuffix(val,"]") {
                inside := strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(val,"["),"]"))
                if inside != "" { for _, part := range splitCSV(inside) { addConfigValue(cfg,key,unquote(strings.TrimSpace(part))) } }
                continue
            }
            switch key {
            case "reportInternalErrors": cfg.ReportInternalErrors = strings.EqualFold(val,"true")
            default: addConfigValue(cfg,key,unquote(val))
            }
        }
    }
}

func stripComment(s string) string {
    inS, inD := false, false
    for i,r := range s { switch r { case '\'': if !inD { inS=!inS }; case '"': if !inS { inD=!inD }; case '#': if !inS && !inD { return s[:i] } } }
    return s
}
func unquote(s string) string { s=strings.TrimSpace(s); if len(s)>=2 { if (s[0]=='"'&&s[len(s)-1]=='"')||(s[0]=='\''&&s[len(s)-1]=='\'') { return s[1:len(s)-1] } }; return s }
func splitCSV(s string) []string { var out []string; var b strings.Builder; inS,inD:=false,false; for _,r:=range s { if r=='\''&&!inD {inS=!inS}; if r=='"'&&!inS {inD=!inD}; if r==','&&!inS&&!inD {out=append(out,b.String()); b.Reset(); continue}; b.WriteRune(r)}; out=append(out,b.String()); return out }
func addConfigValue(cfg *Config, key, val string) { switch key { case "ignoreSigs": cfg.hasIgnoreSigs=true; cfg.IgnoreSigs=append(cfg.IgnoreSigs,val); case "extraIgnoreSigs": cfg.ExtraIgnoreSigs=append(cfg.ExtraIgnoreSigs,val); case "ignoreSigRegexps": cfg.IgnoreSigRegexps=append(cfg.IgnoreSigRegexps,val); case "ignorePackageGlobs": cfg.IgnorePackageGlobs=append(cfg.IgnorePackageGlobs,val); case "ignoreInterfaceRegexps": cfg.IgnoreInterfaceRegexps=append(cfg.IgnoreInterfaceRegexps,val) } }
