func usage(fs *flag.FlagSet) func() {
    return func() {
        fmt.Fprintf(fs.Output(), "wrapcheck: %s\n\nUsage: wrapcheck [-flag] [package]\n\n\nFlags:\n", doc)
        fs.PrintDefaults()
    }
}

func main() {
    // The upstream driver treats -V specially: bare -V is not enough; -V=full is required.
    for _, a := range os.Args[1:] {
        if a == "-V" || a == "--V" {
            fmt.Fprintln(os.Stderr, "wrapcheck: unsupported flag value: -V=true (use -V=full)")
            os.Exit(1)
        }
        if strings.HasPrefix(a, "-V=") || strings.HasPrefix(a, "--V=") {
            v := strings.TrimPrefix(strings.TrimPrefix(a, "--V="), "-V=")
            if v != "full" {
                fmt.Fprintf(os.Stderr, "wrapcheck: unsupported flag value: -V=%s (use -V=full)\n", v)
                os.Exit(1)
            }
            fmt.Println("wrapcheck: version devel")
            os.Exit(0)
        }
    }

    fs := flag.NewFlagSet("wrapcheck", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    var all, diff, fix, flagsFlag, jsonFlag, source, testFlag, verbose bool
    var c int
    var cpuprofile, debug, memprofile, tags, trace string
    fs.BoolVar(&all, "all", false, "no effect (deprecated)")
    fs.IntVar(&c, "c", -1, "display offending line with this many lines of context")
    fs.StringVar(&cpuprofile, "cpuprofile", "", "write CPU profile to this file")
    fs.StringVar(&debug, "debug", "", "debug flags, any subset of \"fpstv\"")
    fs.BoolVar(&diff, "diff", false, "with -fix, don't update the files, but print a unified diff")
    fs.BoolVar(&fix, "fix", false, "apply all suggested fixes")
    fs.BoolVar(&flagsFlag, "flags", false, "print analyzer flags in JSON")
    fs.BoolVar(&jsonFlag, "json", false, "emit JSON output")
    fs.StringVar(&memprofile, "memprofile", "", "write memory profile to this file")
    fs.BoolVar(&source, "source", false, "no effect (deprecated)")
    fs.StringVar(&tags, "tags", "", "no effect (deprecated)")
    fs.BoolVar(&testFlag, "test", true, "indicates whether test files should be analyzed, too")
    fs.StringVar(&trace, "trace", "", "write trace log to this file")
    fs.BoolVar(&verbose, "v", false, "no effect (deprecated)")
    _ = all; _ = diff; _ = fix; _ = cpuprofile; _ = debug; _ = memprofile; _ = source; _ = tags; _ = trace; _ = verbose
    fs.Usage = usage(fs)
    if err := fs.Parse(os.Args[1:]); err != nil {
        if errors.Is(err, flag.ErrHelp) { os.Exit(0) }
        os.Exit(2)
    }
    if flagsFlag {
        printFlagsJSON()
        return
    }
    args := fs.Args()
    if len(args) == 0 {
        fs.Usage()
        os.Exit(1)
    }

    cfg, err := loadConfig()
    if err != nil {
        fmt.Fprintf(os.Stderr, "wrapcheck: %v\n", err)
        os.Exit(1)
    }
    pkgs, err := goList(args)
    if err != nil {
        fmt.Fprint(os.Stderr, err.Error())
        if !strings.HasSuffix(err.Error(), "\n") { fmt.Fprintln(os.Stderr) }
        fmt.Fprintln(os.Stderr, "wrapcheck: analysis skipped due to errors in package")
        os.Exit(1)
    }
    if len(pkgs) == 0 {
        return
    }

    opts := Options{jsonOut: jsonFlag, context: c, test: testFlag}
    allDiags := map[string][]Diagnostic{}
    var plain []Diagnostic
    for _, p := range pkgs {
        if p.Error != nil && p.Error.Err != "" {
            fmt.Fprintf(os.Stderr, "-: %s\nwrapcheck: analysis skipped due to errors in package\n", p.Error.Err)
            os.Exit(1)
        }
        ds, _ := analyzePackage(p, cfg, opts, true)
        if jsonFlag {
            base := filterNonTest(ds)
            if len(base) > 0 { allDiags[p.ImportPath] = base }
            if testFlag && len(p.TestGoFiles) > 0 {
                if len(ds) > 0 { allDiags[p.ImportPath+" ["+p.ImportPath+".test]"] = ds }
            }
        } else {
            plain = append(plain, ds...)
        }
    }
    if jsonFlag {
        printJSONDiagnostics(allDiags)
        return
    }
    sortDiagnostics(plain)
    for _, d := range plain {
        fmt.Fprintf(os.Stderr, "%s: %s\n", d.Posn, d.Message)
        if c >= 0 { printContext(os.Stderr, d.file, d.pos.Line, c) }
    }
    if len(plain) > 0 { os.Exit(3) }
}

